package os.aios.core.automation;
import android.app.Instrumentation;import android.os.Bundle;import org.json.*;import java.util.*;
/** Production scheduler and Android SQLite, isolated database. No model or user operations. */
public final class AssistantSchedulerAcceptance extends Instrumentation {
 int count;AssistantScheduler scheduler;AutomationStore store;String name;
 void check(boolean value,String message){if(!value)throw new AssertionError(message);count++;}
 interface Op{void run()throws Exception;}
 void rejects(Op op,String message)throws Exception{try{op.run();}catch(Exception expected){count++;return;}throw new AssertionError(message);}
 JSONObject definition(String id,boolean screen)throws Exception{return new JSONObject().put("id",id).put("title",id).put("instruction","Read battery only").put("trigger",new JSONObject().put("type","event").put("topic","automation.acceptance.scheduler")).put("capabilities",new JSONArray().put("battery.read")).put("resource_mode",screen?"screen":"headless").put("max_screens",screen?4:0);}
 JSONObject event(String id)throws Exception{return new JSONObject().put("id",id).put("type","automation.acceptance.scheduler").put("time_ms",System.currentTimeMillis()).put("data",new JSONObject());}
 JSONObject create(String id,boolean screen)throws Exception{return scheduler.call("rule.create",definition(id,screen));}
 JSONObject start(JSONObject r,String event)throws Exception{scheduler.accept(r,event(event));JSONArray all=scheduler.call("execution.list",new JSONObject().put("rule_id",r.getString("id"))).getJSONArray("items");return all.getJSONObject(0);}
 JSONObject runState(String id)throws Exception{return scheduler.execution(id);}
 JSONObject checkpoint(JSONObject e,String state)throws Exception{return scheduler.internal("checkpoint",new JSONObject().put("id",e.getString("id")).put("generation",e.getInt("generation")).put("state",state));}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  name="assistant-test-"+UUID.randomUUID()+".db";store=new AutomationStore(getTargetContext(),name);scheduler=new AssistantScheduler(store,getTargetContext(),null);
  JSONObject r=create("dedupe",false),first=start(r,"one");scheduler.accept(r,event("one"));check(scheduler.call("execution.list",new JSONObject()).getJSONArray("items").length()==1,"event deduplication");start(r,"two");scheduler.internal("dispatch",new JSONObject());check(runState(first.getString("id")).getString("state").equals("preparing"),"first ready consumed");check(scheduler.activeHeadless()==1,"same rule serial");
  JSONObject e=runState(first.getString("id"));rejects(()->scheduler.internal("checkpoint",new JSONObject().put("id",e.getString("id")).put("generation",99).put("state","running")),"stale generation rejected");checkpoint(e,"succeeded");scheduler.internal("dispatch",new JSONObject());check(scheduler.activeHeadless()==1,"next occurrence admitted");
  for(int i=0;i<6;i++)start(create("headless"+i,false),"h"+i);scheduler.internal("dispatch",new JSONObject());check(scheduler.activeHeadless()==5,"five headless maximum");
  for(int i=0;i<4;i++)start(create("screen"+i,true),"s"+i);scheduler.internal("dispatch",new JSONObject());JSONArray slots=scheduler.status().getJSONArray("slots");int allocated=0;for(int i=0;i<4;i++)if(!slots.getJSONObject(i).getString("owner").isEmpty())allocated++;check(allocated==4,"four screen reservations independent of headless");String reserved=slots.getJSONObject(0).getString("owner");
  JSONObject waiting=scheduler.internal("screen.request",new JSONObject().put("thread_id","human").put("session_id","human-screen"));check(waiting.getString("state").equals("waiting_resource"),"human waits for confirmed release");check(!runState(reserved).getString("state").equals("pausing"),"reserved not preempted by user");
  JSONObject victim=null;JSONArray runs=scheduler.call("execution.list",new JSONObject()).getJSONArray("items");for(int i=0;i<runs.length();i++)if(runs.getJSONObject(i).optString("pause_reason").equals("preempted"))victim=runs.getJSONObject(i);check(victim!=null,"borrowed task preempted");JSONObject v=victim;rejects(()->checkpoint(v,"paused"),"cannot acknowledge pause with live reservation");scheduler.internal("release.empty",new JSONObject().put("id",v.getString("id")));checkpoint(v,"paused");JSONObject user=scheduler.internal("screen.request",new JSONObject().put("thread_id","human").put("session_id","human-screen"));check(user.getInt("id")>0,"user receives only shared slot");
  scheduler.internal("screen.release",new JSONObject().put("session_id","human-screen"));scheduler.internal("dispatch",new JSONObject());check(runState(v.getString("id")).getString("state").equals("preparing"),"preempted task resumes after release");
  JSONObject manual=runState(v.getString("id"));scheduler.call("execution.pause",new JSONObject().put("id",manual.getString("id")));scheduler.internal("release.empty",new JSONObject().put("id",manual.getString("id")));checkpoint(manual,"paused");scheduler.internal("dispatch",new JSONObject());check(runState(manual.getString("id")).getString("state").equals("paused"),"manual pause never auto resumes");
  JSONObject merged=create("merge",false);merged.put("repeat_policy","coalesce");scheduler.saveRule(merged);start(merged,"merge1");scheduler.accept(merged,event("merge2"));check(scheduler.call("execution.list",new JSONObject().put("rule_id","merge")).getJSONArray("items").length()==1,"coalesce queued events");scheduler.accept(merged,event("merge2"));check(scheduler.execution(scheduler.call("execution.list",new JSONObject().put("rule_id","merge")).getJSONArray("items").getJSONObject(0).getString("id")).getJSONObject("event").getJSONArray("coalesced").length()==1,"coalesced receipt dedup");
  JSONObject paused=scheduler.call("rule.pause",new JSONObject().put("id","merge").put("expected_revision",merged.getLong("revision")));JSONObject updated=definition("merge",false).put("expected_revision",paused.getLong("revision"));check(!scheduler.call("rule.update",updated).getBoolean("enabled"),"editing preserves pause");
  JSONObject invalid=definition("bad",false).put("capabilities",new JSONArray().put("automation.authorization.put"));rejects(()->scheduler.call("rule.create",invalid),"background self-authorization rejected");
  JSONObject security=null;JSONArray active=scheduler.rows("assistant_executions","WHERE state='preparing'");for(int i=0;i<active.length();i++)if(active.getJSONObject(i).getString("resource_mode").equals("headless")){security=active.getJSONObject(i);break;}
  final JSONObject secured=security;check(secured!=null,"active security fixture");scheduler.internal("checkpoint",new JSONObject().put("id",secured.getString("id")).put("generation",secured.getInt("generation")).put("thread_id","security-thread").put("turn_id","security-turn").put("state","running"));
  check(scheduler.internal("identity",new JSONObject().put("thread_id","security-thread").put("turn_id","security-turn")).getBoolean("scheduled"),"native identity accepted");
  rejects(()->scheduler.internal("identity",new JSONObject().put("thread_id","security-thread").put("turn_id","other-turn")),"old native turn rejected");
  check(scheduler.internal("guard",new JSONObject().put("thread_id","security-thread").put("capability","battery.read")).getBoolean("scheduled"),"frozen capability accepted");
  rejects(()->scheduler.internal("guard",new JSONObject().put("thread_id","security-thread").put("capability","notifications.reply")),"ungranted write rejected");
  scheduler.internal("tool.begin",new JSONObject().put("thread_id","security-thread").put("request_id","unknown-tool"));scheduler.internal("tool.finish",new JSONObject().put("thread_id","security-thread").put("request_id","unknown-tool").put("unknown",true));
  rejects(()->scheduler.internal("guard",new JSONObject().put("thread_id","security-thread").put("capability","battery.read")),"unknown external write stops subsequent actions");
  scheduler.internal("shutdown",new JSONObject());check(scheduler.execution(secured.getString("id")).getString("state").equals("pausing"),"authorization stop requires confirmed pause");
  store.close();store=new AutomationStore(getTargetContext(),name);scheduler=new AssistantScheduler(store,getTargetContext(),null);check(scheduler.status().getJSONArray("slots").getJSONObject(0).getString("owner").equals(reserved),"resource survives database reopen");check(scheduler.call("execution.list",new JSONObject()).getJSONArray("items").length()>8,"occurrences survive database reopen");
  JSONObject filtered=new JSONObject().put("type","event").put("topic","notification.posted").put("equals",new JSONObject().put("package","test.app"));
  JSONArray predicates=new JSONArray().put(new JSONObject().put("field","title").put("op","contains").put("value","Pay")).put(new JSONObject().put("field","text").put("op","not_contains").put("value","spam"));filtered.put("conditions",predicates);
  JSONObject notification=new JSONObject().put("type","notification.posted").put("data",new JSONObject().put("package","test.app").put("title","PAY received").put("text","Amount 5"));
  NotificationFilter.validate(filtered);check(scheduler.matches(filtered,notification),"local all case-insensitive match");
  notification.getJSONObject("data").put("text","SPAM");check(!scheduler.matches(filtered,notification),"negative filter before enqueue");
  filtered.put("condition_mode","any");check(scheduler.matches(filtered,notification),"any accepts one predicate");
  notification.getJSONObject("data").put("package","other.app");check(!scheduler.matches(filtered,notification),"package gate remains mandatory for any");notification.getJSONObject("data").put("package","test.app");
  filtered.put("condition_mode","all");notification.getJSONObject("data").put("text","Amount 5").put("content_truncated",true);check(!scheduler.matches(filtered,notification),"truncated negative fails closed");notification.getJSONObject("data").put("content_truncated",false);
  predicates.getJSONObject(0).put("ignore_case",false);check(!scheduler.matches(filtered,notification),"case sensitive match");predicates.getJSONObject(0).put("ignore_case",true);
  for(String op:List.of("equals","starts_with","ends_with")){predicates.getJSONObject(0).put("op",op).put("value",op.equals("equals")?"pay received":op.equals("starts_with")?"pay":"received");check(scheduler.matches(filtered,notification),op+" matches");}
  notification.getJSONObject("data").remove("text");check(!scheduler.matches(filtered,notification),"missing field fails negative");
  JSONObject invalidFilter=new JSONObject(filtered.toString());invalidFilter.getJSONArray("conditions").getJSONObject(0).put("op","regex");rejects(()->NotificationFilter.validate(invalidFilter),"unsupported/unbounded regex rejected");
  invalidFilter.getJSONArray("conditions").getJSONObject(0).put("op","contains").put("value","");rejects(()->NotificationFilter.validate(invalidFilter),"empty predicate rejected");
  check(scheduler.validate(definition("fresh-policy",false)).getString("context_mode").equals("fresh"),"old/missing context defaults fresh");
  check(scheduler.validate(definition("reuse-policy",false).put("context_mode","rule")).getString("context_mode").equals("rule"),"explicit context reuse");
  rejects(()->scheduler.validate(definition("invalid-policy",false).put("context_mode","other")),"unknown context policy rejected");
  String workspaceName="background-list-acceptance.db";try(os.aios.core.workspace.WorkspaceStore w=new os.aios.core.workspace.WorkspaceStore(getTargetContext(),workspaceName)){
   w.call("sync.incremental",new JSONObject().put("thread_id","automation-hidden").put("title","Background acceptance").put("status","completed").put("updated_at",System.currentTimeMillis()).put("items",new JSONArray()));
   check(w.call("session.list",new JSONObject()).toString().contains("automation-hidden"),"fixture visible before marker");
   w.call("sync.automation",new JSONObject().put("thread_id","automation-hidden"));
   check(w.call("session.list",new JSONObject()).toString().indexOf("automation-hidden")<0,"automation marker works before projection");
   w.call("home.snapshot",new JSONObject());check(true,"home ignores hidden automation thread");
  }finally{getTargetContext().deleteDatabase(workspaceName);}
  result.putString("stream","PASS "+count+" isolated scheduler/SQLite assertions\n");finish(-1,result);
 }catch(Throwable failure){result.putString("stream","FAIL after "+count+": "+android.util.Log.getStackTraceString(failure));finish(0,result);}finally{if(scheduler!=null)try{JSONArray a=scheduler.rows("assistant_rules","");for(int i=0;i<a.length();i++){String sub=a.getJSONObject(i).optString("subscription");if(!sub.isEmpty())os.aios.core.events.EventHub.unsubscribe(sub);}}catch(Exception ignored){}if(store!=null)store.close();if(name!=null)getTargetContext().deleteDatabase(name);}}
}
